import os
import time
import requests
from pathlib import Path
from typing import Optional

KIE_API_KEY = os.environ.get("KIE_API_KEY", "")
KIE_API_URL = "https://api.kie.ai/api/v1/runway"

class WANClient:
    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or KIE_API_KEY
        self.base_url = KIE_API_URL
        self.headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

    def generate_video(self, prompt: str, duration: int = 5, output_path: Optional[str] = None) -> str:
        valid_durations = [5, 8, 10]
        if duration not in valid_durations:
            duration = 5 if duration <= 6 else (8 if duration <= 9 else 10)

        if not self.api_key:
            return self._generate_placeholder(prompt, duration, output_path)

        try:
            create_response = requests.post(
                f"{self.base_url}/generate",
                headers=self.headers,
                json={
                    "prompt": prompt,
                    "duration": duration,
                    "quality": "720p",
                    "aspectRatio": "16:9",
                    "waterMark": ""
                },
                timeout=30
            )

            if create_response.status_code != 200:
                print(f"Runway API creation failed: {create_response.status_code}")
                return self._generate_placeholder(prompt, duration, output_path)

            result = create_response.json()
            if result.get("code") != 200:
                print(f"Runway API error: {result.get('msg', 'Unknown error')}")
                return self._generate_placeholder(prompt, duration, output_path)

            task_id = result.get("data", {}).get("taskId")

            if not task_id:
                print("No task ID returned from Runway API")
                return self._generate_placeholder(prompt, duration, output_path)

            max_attempts = 60
            for attempt in range(max_attempts):
                status_response = requests.get(
                    f"{self.base_url}/record-detail?taskId={task_id}",
                    headers=self.headers,
                    timeout=30
                )

                if status_response.status_code == 200:
                    status_result = status_response.json()
                    if status_result.get("code") == 200:
                        status_data = status_result.get("data", {})
                        state = status_data.get("state", "")

                        if state == "success":
                            video_info = status_data.get("videoInfo", {})
                            video_url = video_info.get("videoUrl")
                            if video_url:
                                return self._download_video(video_url, output_path)
                        elif state == "fail":
                            fail_msg = status_data.get("failMsg", "Unknown error")
                            print(f"Runway generation failed: {fail_msg}")
                            return self._generate_placeholder(prompt, duration, output_path)
                        elif state in ["wait", "queueing", "generating"]:
                            print(f"Runway status: {state}")

                time.sleep(5)

            print("Runway generation timed out")
            return self._generate_placeholder(prompt, duration, output_path)

        except Exception as e:
            print(f"Runway API error: {e}")
            return self._generate_placeholder(prompt, duration, output_path)

    def _download_video(self, video_url: str, output_path: Optional[str]) -> str:
        response = requests.get(video_url, stream=True, timeout=120)
        if response.status_code == 200:
            output_path = output_path or f"runway_video_{int(time.time())}.mp4"
            with open(output_path, "wb") as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)
            return output_path
        raise Exception(f"Failed to download video: {response.status_code}")

    def _generate_placeholder(self, prompt: str, duration: int, output_path: Optional[str]) -> str:
        try:
            from moviepy import ColorClip

            output_path = output_path or f"placeholder_{int(time.time())}.mp4"

            bg = ColorClip(size=(1280, 720), color=(30, 30, 60), duration=duration)

            bg.write_videofile(
                output_path,
                fps=24,
                codec="libx264",
                audio=False,
                logger=None
            )

            bg.close()
            return output_path

        except Exception as e:
            print(f"Placeholder generation error: {e}")
            return self._create_ffmpeg_video(output_path, duration)

    def _create_ffmpeg_video(self, output_path: Optional[str], duration: int) -> str:
        import subprocess

        output_path = output_path or f"minimal_{int(time.time())}.mp4"
        cmd = [
            "ffmpeg", "-y", "-f", "lavfi",
            "-i", f"color=c=0x1e3c72:s=1280x720:d={duration}",
            "-c:v", "libx264", "-pix_fmt", "yuv420p",
            output_path
        ]
        subprocess.run(cmd, capture_output=True)
        return output_path

tts/generate_audio.py.content:
import os
import time
import requests
from pathlib import Path

NARAKEET_API_KEY = os.environ.get("NARAKEET_API_KEY", "")
NARAKEET_VOICE = "ravi"
NARAKEET_STREAMING_LIMIT = 1024


class TTSGenerationError(Exception):
    """Raised when TTS generation fails - NO fallback to gTTS."""
    pass


def _narakeet_streaming(narration: str, output_path: str, section_id: int) -> str:
    """Use Narakeet streaming API for short text (<= 1024 chars)."""
    response = requests.post(
        f"https://api.narakeet.com/text-to-speech/mp3?voice={NARAKEET_VOICE}",
        headers={
            "x-api-key": NARAKEET_API_KEY,
            "Content-Type": "text/plain",
            "accept": "application/octet-stream"
        },
        data=narration.encode('utf-8'),
        timeout=120
    )

    if response.status_code == 200:
        with open(output_path, 'wb') as f:
            f.write(response.content)
        duration = response.headers.get('x-duration-seconds', 'unknown')
        print(f"[TTS] Section {section_id}: Narakeet streaming SUCCESS - {output_path} ({duration}s)")
        return output_path
    else:
        raise TTSGenerationError(
            f"Narakeet streaming API failed: {response.status_code} - {response.text[:200]}"
        )


def _narakeet_polling(narration: str, output_path: str, section_id: int) -> str:
    """Use Narakeet polling API for long text (> 1024 chars)."""
    print(f"[TTS] Section {section_id}: Using Narakeet polling API (text_len={len(narration)})")

    response = requests.post(
        f"https://api.narakeet.com/text-to-speech/mp3?voice={NARAKEET_VOICE}",
        headers={
            "x-api-key": NARAKEET_API_KEY,
            "Content-Type": "text/plain"
        },
        data=narration.encode('utf-8'),
        timeout=30
    )

    if response.status_code != 200:
        raise TTSGenerationError(
            f"Narakeet polling API submission failed: {response.status_code} - {response.text[:200]}"
        )

    result = response.json()
    status_url = result.get('statusUrl')

    if not status_url:
        raise TTSGenerationError("Narakeet polling API did not return statusUrl")

    max_wait = 300
    poll_interval = 3
    elapsed = 0

    while elapsed < max_wait:
        status_response = requests.get(
            status_url,
            headers={"x-api-key": NARAKEET_API_KEY},
            timeout=30
        )

        if status_response.status_code != 200:
            raise TTSGenerationError(
                f"Narakeet status poll failed: {status_response.status_code}"
            )

        status_data = status_response.json()

        if status_data.get('finished'):
            if status_data.get('succeeded'):
                audio_url = status_data.get('result')
                if not audio_url:
                    raise TTSGenerationError("Narakeet finished but no result URL")

                audio_response = requests.get(audio_url, timeout=120)
                if audio_response.status_code != 200:
                    raise TTSGenerationError(
                        f"Failed to download audio: {audio_response.status_code}"
                    )

                with open(output_path, 'wb') as f:
                    f.write(audio_response.content)

                duration = status_data.get('durationInSeconds', 'unknown')
                print(f"[TTS] Section {section_id}: Narakeet polling SUCCESS - {output_path} ({duration}s)")
                return output_path
            else:
                raise TTSGenerationError("Narakeet polling task failed")

        time.sleep(poll_interval)
        elapsed += poll_interval

    raise TTSGenerationError(f"Narakeet polling timed out after {max_wait}s")


def generate_section_audio(section: dict, output_dir: str) -> str:
    """Generate audio for a section using Narakeet TTS.

    FAIL-FAST: No fallback to gTTS. Raises TTSGenerationError if Narakeet fails.
    Uses streaming API for short text, polling API for long text.
    """
    section_id = section.get("id", 1)
    narration = section.get("narration", "")

    if not narration:
        segments = section.get("segments", [])
        narration = " ".join([seg.get("text", "") for seg in segments])

    if not narration:
        narration = f"Section {section_id}: {section.get('title', 'Educational content')}"

    output_path = str(Path(output_dir) / f"section_{section_id}.mp3")

    if not NARAKEET_API_KEY:
        raise TTSGenerationError(
            "NARAKEET_API_KEY not configured. TTS requires Narakeet API."
        )

    print(f"[TTS] Section {section_id}: Generating audio (voice={NARAKEET_VOICE}, text_len={len(narration)})")

    try:
        if len(narration) <= NARAKEET_STREAMING_LIMIT:
            return _narakeet_streaming(narration, output_path, section_id)
        else:
            return _narakeet_polling(narration, output_path, section_id)
    except requests.exceptions.RequestException as e:
        raise TTSGenerationError(f"Narakeet API request failed: {e}")


def generate_all_audio(presentation: dict, output_dir: str) -> list:
    """Generate audio for all sections in presentation."""
    os.makedirs(output_dir, exist_ok=True)

    audio_files = []
    sections = presentation.get("sections", presentation.get("topics", []))

    for section in sections:
        audio_path = generate_section_audio(section, output_dir)
        audio_files.append({
            "section_id": section.get("id"),
            "section_type": section.get("section_type", "content"),
            "audio_path": audio_path
        })

    return audio_files

